    secret = os.getenv('CAPSULE_SECRET')
    if not secret:
        raise RuntimeError("CAPSULE_SECRET environment variable not set")
    return f"{json.dumps(data)}:{secret}"

def render_template(token: str, template_path: str) -> None:
    secret = os.getenv('CAPSULE_SECRET')
    if not secret:
        raise RuntimeError("CAPSULE_SECRET environment variable not set")

    token_parts = token.split(':', 1)
    if len(token_parts) != 2:
        sys.stderr.write("invalid token\n")
        sys.exit(3)

    stored_secret = token_parts[1]
    if secret != stored_secret:
        sys.stderr.write("invalid token\n")
        sys.exit(3)

    data = json.loads(token_parts[0])
    with open(template_path, 'r') as f:
        template = f.read()

    def evaluate_expression(expr: str) -> Any:
        try:
            return eval(expr, {'__builtins__': None}, data)
        except:
            raise ValueError(f"Invalid expression: {expr}")

    def replace_placeholder(match):
        expr = match.group(1)
        try:
            value = evaluate_expression(expr)
            if isinstance(value, (int, float)):
                if isinstance(value, int):
                    return str(value)
                return f"{value:.0f}" if value.is_integer() else str(value)
            elif isinstance(value, str):
                return value
            else:
                return str(value)
        except ValueError as e:
            sys.stderr.write(f"Invalid expression: {e}\n")
            sys.exit(3)

    rendered = re.sub(r'\{\{([^}]+)\}\}', replace_placeholder, template)
    print(rendered)

