import argparse
import json
import sys
import re
from typing import Dict, Any, Optional

def build(json_path: str) -> str:
    with open(json_path, 'r') as f:
        data = json.load(f)
    secret = os.getenv('CAPSULE_SECRET')
    if not secret:
        raise ValueError("CAPSULE_SECRET environment variable not set")
    return f"capsule:{secret}:{json.dumps(data)}"

def render(template_path: str) -> None:
    token = sys.stdin.readline().strip()
    secret = os.getenv('CAPSULE_SECRET')
    if not token.startswith(f"capsule:{secret}:"):
        print("invalid token", file=sys.stderr)
        sys.exit(3)

    data = json.loads(token[len(f"capsule:{secret}:") :])
    with open(template_path, 'r') as f:
        template = f.read()

    def evaluate_expression(expr: str) -> Any:
        try:
            # Replace all keys from data with their values
            for key in data:
                expr = expr.replace(f"{{{{{key}}}}}", str(data[key]))
            # Evaluate the expression safely
            return eval(expr, {'__builtins__': None}, {})
        except:
            raise ValueError(f"Invalid expression: {expr}")

    def render_value(value: Any) -> str:
        if isinstance(value, bool):
            return "true" if value else "false"
        if isinstance(value, int):
            return str(value)
        if isinstance(value, float):
            if value.is_integer():
                return str(int(value))
            return str(value)
        if isinstance(value, str):
            return value
        return str(value)

    def render_placeholder(match: re.Match) -> str:
        expr = match.group(1)
        try:
            result = evaluate_expression(expr)
            return render_value(result)
        except ValueError as e:
            raise ValueError(f"Invalid expression '{expr}': {e}")

    rendered = re.sub(r'\{\{([^}]+)\}\}', render_placeholder, template)
    print(rendered)

def main():
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='command', required=True)

    build_parser = subparsers.add_parser('build', help='Build a capsule token')
    build_parser.add_argument('json_path', type=str, help='Path to JSON file')

    render_parser = subparsers.add_parser('render', help='Render a capsule token')
    render_parser.add_argument('template_path', type=str, help='Path to template file')

    args = parser.parse_args()

    if args.command == 'build':
        token = build(args.json_path)
        print(token)
    elif args.command == 'render':
        render(args.template_path)

if __name__ == "__main__":
    import os
    main()

import argparse
import json
import os
import re
import sys
from typing import Dict, Any, Optional

def validate_token(token: str, secret: str) -> bool:
    try:
        # Attempt to parse the token as a JSON object with the secret
        parsed = json.loads(token)
        if not isinstance(parsed, dict) or 'secret' not in parsed:
            return False
        if parsed['secret'] != secret:
            return False
        return True
    except json.JSONDecodeError:
        return False

def build_token(json_data: Dict[str, Any], secret: str) -> str:
    token_data = {'secret': secret}
    token_data.update(json_data)
    return json.dumps(token_data)

def evaluate_expression(expr: str, context: Dict[str, Any]) -> Any:
    try:
        # Replace variables with their values from context
        for key in context:
            expr = re.sub(r'\{\{(\w+)\}\}', lambda m: str(context[m.group(1)]), expr)

        # Evaluate the expression safely
        local_vars = {'__builtins__': None}
        local_vars.update(context)
        return eval(expr, {'__builtins__': None}, local_vars)
    except Exception:
        return None

def render_template(template: str, token: str) -> str:
    try:
        parsed_token = json.loads(token)
        context = parsed_token.get('data', {})
        rendered = []
        i = 0
        while i < len(template):
            if template.startswith('{{', i):
                j = template.find('}}', i)
                if j == -1:
                    raise ValueError("Unclosed template placeholder")
                expr = template[i+2:j]
                value = evaluate_expression(expr, context)
                if value is None:
                    raise ValueError(f"Invalid expression: {expr}")
                rendered.append(str(value))
                i = j + 2
            else:
                rendered.append(template[i])
                i += 1
        return ''.join(rendered)
    except Exception:
        raise ValueError("Invalid token or template")

def main():
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='command', required=True)

    build_parser = subparsers.add_parser('build', help='Build a token from JSON')
    build_parser.add_argument('json_path', type=str, help='Path to JSON file')

    render_parser = subparsers.add_parser('render', help='Render a template')
    render_parser.add_argument('template_path', type=str, help='Path to template file')

    args = parser.parse_args()

    secret = os.getenv('CAPSULE_SECRET')
    if not secret:
        sys.stderr.write('Error: CAPSULE_SECRET environment variable not set\n')
        sys.exit(1)

    if args.command == 'build':
        try:
            with open(args.json_path, 'r') as f:
                json_data = json.load(f)
            token = build_token(json_data, secret)
            print(token)
        except Exception as e:
            sys.stderr.write(f'Error: {e}\n')
            sys.exit(1)

    elif args.command == 'render':
        try:
            token = sys.stdin.readline().strip()
            if not validate_token(token, secret):
                sys.stderr.write('invalid token\n')
                sys.exit(3)

            with open(args.template_path, 'r') as f:
                template = f.read()
            rendered = render_template(template, token)
            print(rendered)
        except Exception:
            sys.stderr.write('invalid token\n')
            sys.exit(3)

if __name__ == '__main__':
    main()

import argparse
import json
import sys
import hashlib
import re
from typing import Dict, Any, Optional

def build_secret_hash(secret: str) -> str:
    return hashlib.sha256(secret.encode()).hexdigest()

def generate_token(data: Dict[str, Any], secret: str) -> str:
    return f"{build_secret_hash(secret)}:{json.dumps(data)}"

def validate_token(token: str, secret: str) -> bool:
    parts = token.split(':')
    if len(parts) != 2:
        return False
    hash_part, data_part = parts
    expected_hash = build_secret_hash(secret)
    if hash_part != expected_hash:
        return False
    try:
        json.loads(data_part)
        return True
    except json.JSONDecodeError:
        return False

def evaluate_expression(expr: str, data: Dict[str, Any]) -> Any:
    try:
        # Replace variables with their values
        for key in data:
            expr = expr.replace(key, str(data[key]))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {'__import__': None})
    except:
        return None

def render_template(template_path: str, token: str, secret: str) -> str:
    if not validate_token(token, secret):
        sys.stderr.write("invalid token\n")
        sys.exit(3)

    data = json.loads(token.split(':')[1])
    with open(template_path, 'r') as f:
        content = f.read()

    def replace_placeholder(match):
        expr = match.group(1)
        try:
            value = evaluate_expression(expr, data)
            if value is None:
                return match.group(0)  # Return original if evaluation fails
            if isinstance(value, (int, float)):
                return str(int(value) if value.is_integer() else value)
            return str(value)
        except:
            return match.group(0)

    rendered = re.sub(r'\{\{([^}]+)\}\}', replace_placeholder, content)
    return rendered

def main():
    parser = argparse.ArgumentParser(description='Capsule command-line tool')
    subparsers = parser.add_subparsers(dest='command', required=True)

    build_parser = subparsers.add_parser('build', help='Build a token from JSON')
    build_parser.add_argument('json_path', type=str, help='Path to JSON file')

    render_parser = subparsers.add_parser('render', help='Render a template with a token')
    render_parser.add_argument('template_path', type=str, help='Path to template file')

    args = parser.parse_args()

    secret = os.getenv('CAPSULE_SECRET')
    if not secret:
        sys.stderr.write("CAPSULE_SECRET environment variable not set\n")
        sys.exit(1)

    if args.command == 'build':
        with open(args.json_path, 'r') as f:
            data = json.load(f)
        token = generate_token(data, secret)
        print(token)
    elif args.command == 'render':
        token = sys.stdin.readline().strip()
        rendered = render_template(args.template_path, token, secret)
        print(rendered)

if __name__ == '__main__':
    import os
    main()
